-- Read-only backup role for Jawwid Chat. Run ONCE as the migration owner (Supabase: `postgres`).
-- Usage:  psql -v ON_ERROR_STOP=1 -v pw="$(cat password-file)" -f create-jawwid-backup-role.sql "$ADMIN_URL"
-- The password is generated by the owner and never written to the repository or to chat.
CREATE ROLE jawwid_backup LOGIN PASSWORD :'pw' BYPASSRLS NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION CONNECTION LIMIT 2;
ALTER ROLE jawwid_backup SET statement_timeout = 0;
ALTER ROLE jawwid_backup SET default_transaction_read_only = on;
GRANT USAGE ON SCHEMA chat TO jawwid_backup;
GRANT SELECT ON ALL TABLES IN SCHEMA chat TO jawwid_backup;
GRANT SELECT ON ALL SEQUENCES IN SCHEMA chat TO jawwid_backup;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA chat GRANT SELECT ON TABLES TO jawwid_backup;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA chat GRANT SELECT ON SEQUENCES TO jawwid_backup;
